sql.if:
AND EXISTS (
  SELECT 1 FROM event_users eu
  WHERE eu.space_id = e.space_id
    AND eu.event_id = e.id
    AND eu.user_id = #{userId}
)

mapper.select:
SELECT count(*)
FROM events e
WHERE e.space_id = #{spaceId}

SELECT e.id AS event_id, e.name, e.lifecycle_status
FROM events e
WHERE e.space_id = #{spaceId}
